const original = $items('Set Job Input')[0].json;
const fetched = $input.first().json;

const manualRequirement = String(original.rawRequirement || '').trim();
const placeholderPattern = /^Paste the job post text here/i;

const firstString = (...values) => {
  for (const value of values) {
    if (typeof value === 'string' && value.trim()) return value;
  }
  return '';
};

const stripHtml = (text) => String(text || '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/\s+/g, ' ')
  .trim();

const fetchedRaw = firstString(
  fetched.data,
  fetched.body,
  fetched.response,
  fetched.text,
  fetched.html,
  typeof fetched === 'string' ? fetched : ''
);

const fetchedText = stripHtml(fetchedRaw).slice(0, 30000);
let rawRequirement = '';
let requirementSource = '';

if (manualRequirement && !placeholderPattern.test(manualRequirement)) {
  rawRequirement = manualRequirement;
  requirementSource = 'manual';
} else if (fetchedText.length >= 200) {
  rawRequirement = fetchedText;
  requirementSource = 'job_link_fetch';
} else {
  rawRequirement = 'Job page could not be fetched automatically. Use the Job Link and add the full job requirement manually if this opportunity looks promising.';
  requirementSource = 'fetch_failed';
}

return [{
  json: {
    ...original,
    rawRequirement,
    requirementSource,
    fetchNote: requirementSource === 'fetch_failed' ? 'The site may block automated fetching or require login.' : ''
  }
}];

const response = $input.first().json;
const original = $items('Prepare Job Text')[0].json;
const text = response.choices?.[0]?.message?.content || response.body?.choices?.[0]?.message?.content || '';
const match = text.match(/\{[\s\S]*\}/);
if (!match) {
  throw new Error('OpenAI response did not contain JSON: ' + text);
}

let analysis;
try {
  analysis = JSON.parse(match[0]);
} catch (error) {
  throw new Error('Could not parse OpenAI JSON: ' + error.message + ' Raw: ' + text);
}

const score = (value) => {
  const number = Number(value);
  if (Number.isNaN(number)) return 0;
  return Math.max(1, Math.min(10, Math.round(number)));
};

const yourMatchScore = score(analysis.yourMatchScore);
const aiLeverageScore = score(analysis.aiLeverageScore);
const asyncFitScore = score(analysis.asyncFitScore);
const learningValue = score(analysis.learningValue);
const deliveryRisk = score(analysis.deliveryRisk);
const starterFitScore = score(analysis.starterFitScore);
const opportunityScore = yourMatchScore + aiLeverageScore + asyncFitScore + learningValue - deliveryRisk;
const fullJobRequirement = original.rawRequirement || analysis.fullJobRequirement || '';
const notes = [analysis.notes || '', original.fetchNote || ''].filter(Boolean).join(' | ');
const applyPriority = analysis.applyPriority || 'Save for Learning';
const statusByPriority = {
  'Apply Now': 'Shortlisted',
  'Build Demo First': 'Needs Demo',
  'Save for Learning': 'Learning',
  'Skip': 'Archived'
};

return [{
  json: {
    'Date Added': new Date().toISOString().slice(0, 10),
    'Source': original.source || '',
    'Job Title': original.jobTitle || '',
    'Job Link': original.jobLink || '',
    'Recruiter Contact': analysis.recruiterContact || 'Not provided',
    'Raw Requirement': original.rawRequirement || '',
    'Full Job Requirement': fullJobRequirement,
    'Job Category': analysis.jobCategory || '',
    'Real Need': analysis.realNeed || '',
    'Deliverable': analysis.deliverable || '',
    'Required Tools': analysis.requiredTools || '',
    'Required Skills': analysis.requiredSkills || '',
    'Your Match Score': yourMatchScore,
    'AI Leverage Score': aiLeverageScore,
    'Async Fit Score': asyncFitScore,
    'Learning Value': learningValue,
    'Delivery Risk': deliveryRisk,
    'Opportunity Score': opportunityScore,
    'Starter Fit Score': starterFitScore,
    'Can Start Now': analysis.canStartNow || 'Maybe',
    'Apply Priority': applyPriority,
    'Starter Fit Reason': analysis.starterFitReason || '',
    'Missing Proof': analysis.missingProof || '',
    'First 2-Hour Prep': analysis.firstTwoHourPrep || '',
    'Recommended Skillset': analysis.recommendedSkillset || '',
    'Learning Resource': analysis.learningResource || '',
    'Learning Resource Links': analysis.learningResourceLinks || '',
    'Knowledge Base Topic': analysis.knowledgeBaseTopic || '',
    'Best Practice': analysis.bestPractice || '',
    'Suggested Pitch': analysis.suggestedPitch || '',
    'Next Action': analysis.nextAction || '',
    'Status': statusByPriority[applyPriority] || 'Learning',
    'Notes': notes
  }
}];
